def transform(grid):
    rows, cols = len(grid), len(grid[0])
    output = [[9] * cols for _ in range(rows)]

    # 2s shift right by 1
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                output[r][c + 1] = 2

    # Horizontal 5s at original positions (4,12), (4,13), (5,12) become 8s
    # 5s shift left by 3 to (4,9), (4,10), (5,9), (5,10)
    for r, c in [(4, 12), (4, 13), (5, 12)]:
        output[r][c] = 8
    for r, c in [(4, 9), (4, 10), (5, 9), (5, 10)]:
        output[r][c] = 5

    return output


